function validate([n, edges]) {
  if (!Number.isInteger(n) || n < 1 || n > 500) return 'n is between 1 and 500.';
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > 10000) return 'edges needs 1 to 10000 pairs.';
  const seen = new Set();
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 2) return 'Each edge is a pair [a, b].';
    const [a, b] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 1 || a > n || b < 1 || b > n) return 'Edge ends are nodes from 1 to n.';
    if (a === b) return 'An edge must join two different nodes.';
    const key = a < b ? a + ',' + b : b + ',' + a;
    if (seen.has(key)) return 'Two nodes are joined by at most one edge.';
    seen.add(key);
  }
  return null;
}

