function magnificentSets(n, edges) {
  const graph = Array.from({ length: n + 1 }, () => []);
  for (const [a, b] of edges) {
    graph[a].push(b);
    graph[b].push(a);
  }

  // best: component's smallest node -> most groups found for that component
  const best = new Map();
  for (let source = 1; source <= n; source++) {
    const depth = new Array(n + 1).fill(-1);
    depth[source] = 0;
    const queue = [source];
    let root = source;
    let levels = 0;
    for (let head = 0; head < queue.length; head++) {
      const node = queue[head];
      root = Math.min(root, node);
      levels = Math.max(levels, depth[node] + 1);
      for (const next of graph[node]) {
        if (depth[next] === -1) {
          depth[next] = depth[node] + 1;
          queue.push(next);
        } else if (depth[next] === depth[node]) {
          return -1;
        }
      }
    }
    best.set(root, Math.max(best.get(root) ?? 0, levels));
  }

  let total = 0;
  for (const groups of best.values()) {
    total += groups;
  }
  return total;
}

