function magnificentSets(n, edges) {
  // Try every labelling of nodes with groups 1..n; keep those that obey every edge
  // and use each group number from 1 to the largest one.
  const earlier = Array.from({ length: n + 1 }, () => []);
  for (const [a, b] of edges) {
    if (a < b) earlier[b].push(a); else earlier[a].push(b);
  }
  const label = new Array(n + 1).fill(0);
  let answer = -1;
  const place = node => {
    if (node > n) {
      const used = new Set(label.slice(1));
      const top = Math.max(...used);
      if (used.size === top) answer = Math.max(answer, top);
      return;
    }
    for (let g = 1; g <= n; g++) {
      if (earlier[node].every(other => Math.abs(label[other] - g) === 1)) {
        label[node] = g;
        place(node + 1);
      }
    }
    label[node] = 0;
  };
  place(1);
  return answer;
}

