function generate(rand, size) {
  const n = size === 'large' ? 500 : 2 + Math.floor(rand() * 5);
  const pairs = new Set();
  const edges = [];
  const add = (a, b) => {
    if (a === b) return;
    const key = a < b ? a + ',' + b : b + ',' + a;
    if (pairs.has(key)) return;
    pairs.add(key);
    edges.push([a, b]);
  };
  const bipartite = rand() < (size === 'large' ? 0.85 : 0.6);
  const side = Array.from({ length: n + 1 }, () => (rand() < 0.5 ? 0 : 1));
  if (size === 'large') {
    // Several components: each is a random long-ish tree plus extra edges inside it.
    const parts = 1 + Math.floor(rand() * 8);
    const order = Array.from({ length: n }, (_, i) => i + 1);
    for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
    const comp = new Array(n + 1).fill(0);
    let first = 0;
    for (let i = 0; i < n; i++) {
      const node = order[i];
      comp[node] = Math.floor((i * parts) / n);
      if (i === 0 || comp[node] !== comp[order[i - 1]]) { first = i; continue; }
      const parent = order[Math.max(first, i - 1 - Math.floor(rand() * 4))];
      side[node] = 1 - side[parent];
      add(parent, node);
    }
    // groups[c][x]: nodes of component c on side x; extra edges join opposite sides of one component.
    const groups = Array.from({ length: parts }, () => [[], []]);
    for (let node = 1; node <= n; node++) groups[comp[node]][side[node]].push(node);
    const extra = Math.floor(rand() * 1400);
    const target = Math.min(1900, edges.length + extra);
    for (let tries = 0; tries < 4 * extra && edges.length < target; tries++) {
      const a = 1 + Math.floor(rand() * n);
      const others = groups[comp[a]][1 - side[a]];
      if (others.length) add(a, others[Math.floor(rand() * others.length)]);
    }
    // One edge inside a side makes an odd cycle, so the answer is -1.
    if (!bipartite) {
      const c = Math.floor(rand() * parts);
      const same = groups[c][0].length >= 2 ? groups[c][0] : groups[c][1];
      add(same[0], same[same.length - 1]);
    }
  } else {
    for (let a = 1; a <= n; a++) {
      for (let b = a + 1; b <= n; b++) {
        if (bipartite && side[a] === side[b]) continue;
        if (rand() < 0.45) add(a, b);
      }
    }
    if (edges.length === 0) add(1, 2);
  }
  return [n, edges];
}
